class string_buf;
class stringx
{
protected:
    char *chars;
    string_buf *my_buf;
public:
    stringx(const char *);
    stringx(const stringx &);
    ~stringx();
};

class entity;
struct SurferTrick
{
    int trick_id;
    int anim_id;
    int board_anim_id;
    int flags;
    int IK_flags;
    int trickbook_type;
    int trick_type;
    unsigned char button1, button2, button3;
    char button1_string[16], button2_string[16], button3_string[16];
    int Time, Points;
};

extern stringx g_surfer_anims[];
extern SurferTrick GTrickList[];

enum { TRICK_EXIT_5 = 40, TRICK_EXIT_4 = 47 };

class FEEntityManager
{
public:
    entity *surfer_ent;
    char pad04[0x220];
    int next_anim;
    int cur_anim;
    int cur_b_anim;
    int cur_trick_anim;
    int cur_trick;
    int cur_state;
    int last_state;
    bool op_ext;
    bool forward;
    bool loop_around;
    char pad23f[0x38];
    bool trick_playing;

    enum { SA_IDLE, SA_SPECIAL_OCC, SA_OCC_1, SA_OCC_2, SA_SELECT, SA_TRICK };
    void Anim(stringx anim, float blend_time, bool loop, float time);
    void TrickPlay(int anim_id);
};

void FEEntityManager::TrickPlay(int anim_id)
{
	float blend_time = 0.3f;
	if(anim_id == cur_trick_anim || cur_trick_anim == -2) blend_time = 0.0f;

	if(surfer_ent)
	{
		if(anim_id != -1)
		{
			Anim(g_surfer_anims[anim_id], blend_time, false, 0.0f);
			trick_playing = true;
		}
		else
		{
			//  hack for exit moves to pop to idle
			for (int n = TRICK_EXIT_5; n <= TRICK_EXIT_4; n++)
			{
				if (GTrickList[n].anim_id == cur_trick_anim)
					blend_time = 0.0f;
			}

			stringx anim = "ALL_TRK_TUBE_FS_1";
			Anim(anim, blend_time, false, 0.0f);
			trick_playing = false;
		}
		next_anim = SA_TRICK;
		cur_anim = SA_TRICK;
		cur_trick_anim = anim_id;
	}
}
